    {
        proof { const_facts(); }
        let j = self.segment_ptr.addr()
          + SIZEOF_SEGMENT_HEADER
          + SLICES_PER_SEGMENT as usize * SIZEOF_PAGE_HEADER;
        self.segment_ptr.with_addr(j) as *mut Page
    }

