let cas_result = atomic_with_ghost!(
    &pag.xthread_free.atomic => compare_exchange_weak(mask, mask1);
    update v_old -> v_new;
    returning cas_result;
    ghost g =>
{
    pag.xthread_free.emp_inst.borrow().agree(pag.xthread_free.emp.borrow(), &g.0);
    if cas_result.is_ok() {
        let tracked (emp_token, pair_opt) = g;
        let tracked (delay_token, ll) = pair_opt.tracked_unwrap();
        if use_delayed {
            let tracked (new_delay_token, new_delay_actor) =
                mim_instance.delay_enter_freeing(
                    dealloc.block_id().page_id,
                    dealloc.block_id(),
                    delay_token,
                    mim_block_opt.tracked_borrow()
                );
            g = (emp_token, Some((new_delay_token, ll)));
            delay_actor_token_opt = Some(new_delay_actor);
        } else {
            let tracked mut ll_ref = Tracked(ll);
            LL::ghost_insert_block(
                &mut ll_ref,
                ptr,
                ptr_mem.tracked_unwrap(),
                raw_mem.tracked_unwrap(),
                mim_block_opt.tracked_unwrap(),
                exposed.tracked_unwrap()
            );
            g = (emp_token, Some((delay_token, ll_ref.get())));
            mim_block_opt = None;
            perm = PointsToRaw::empty(ptr@.provenance);
        }
    } else {
        if !use_delayed {
            let tracked mut pt = ptr_mem.tracked_unwrap();
            let tracked rm = raw_mem.tracked_unwrap();
            pt.leak_contents();
            perm = pt.into_raw().join(rm);
        }
    }
});

